import {createIndex} from './engine.mjs';
const count=Number(document.documentElement.dataset.rows);
document.querySelector('#root').innerHTML=`<main><h1>Indexed records</h1><button id="load">Load</button><label>Search<input aria-label="Search" id="search"></label><label>Region<select aria-label="Region" id="region"><option value="">All</option>${['North','South','East','West'].map(r=>`<option>${r}</option>`).join('')}</select></label><label>Month<select aria-label="Month" id="month"><option value="">All</option>${Array.from({length:12},(_,i)=>`<option>${i+1}</option>`).join('')}</select></label><label>Sort<select aria-label="Sort" id="sort"><option value="id-asc">ID ascending</option><option value="cents-desc">Cents descending</option></select></label><button id="next">Next page</button><button id="export">Export</button><p aria-label="Status" id="status">waiting</p><p>Matching rows: <output aria-label="Matching rows" id="matching">0</output></p><p>Page: <output aria-label="Page" id="page">1</output></p><table><thead><tr><th>ID</th><th>Customer</th><th>Region</th><th>Cents</th><th>Month</th></tr></thead><tbody></tbody></table></main>`;
const names=['load','search','region','month','sort','next','export','status','matching','page'];const ui=Object.fromEntries(names.map(id=>[id,document.getElementById(id)]));let index=createIndex(),page=1,selected=[],current;
const settings=()=>({search:ui.search.value,region:ui.region.value,month:ui.month.value,sort:ui.sort.value});
function render(){selected=index.query(settings());const pages=Math.max(1,Math.ceil(selected.length/100));page=Math.min(page,pages);ui.matching.textContent=String(selected.length);ui.page.textContent=String(page);ui.next.disabled=page>=pages;const body=document.querySelector('tbody');body.replaceChildren();for(const row of selected.slice((page-1)*100,page*100)){const tr=document.createElement('tr');for(const name of ['id','customer','region','cents','month']){const td=document.createElement('td');td.textContent=String(row[name]);tr.append(td);}body.append(tr);}}
ui.load.onclick=async()=>{const token={};current=token;index=createIndex();page=1;ui.status.textContent='indexing';ui.matching.textContent='0';try{await index.load(count,(done,total)=>{if(current===token)ui.status.textContent=`indexing ${done}/${total}`;});if(current!==token)return;ui.status.textContent='ready';render();}catch(error){if(current!==token)return;ui.status.textContent=String(error);}};
for(const name of ['search','region','month','sort'])ui[name].addEventListener(name==='search'?'input':'change',()=>{page=1;try{render();}catch(error){ui.status.textContent=String(error);}});
ui.next.onclick=()=>{page++;render();};
ui.export.onclick=()=>{render();const url=URL.createObjectURL(new Blob([JSON.stringify(selected)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='records.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
